-- ===================== H5 DATA DUMP (temporary, do not ship) =====================
local function __dumpDir()
	local base = nil

	pcall(function()
		base = lc.File:getWritablePath()
	end)

	if base == nil or base == "" then
		base = "/data/data/com.tuoyin.jdzc.android.guopan/files/"
	end

	return base .. "h5dump_"
end
local __dumpSeen = {}

local function __dump_esc(s)
	local out = {}
	for i = 1, #s do
		local b = string.byte(s, i)
		if b == 34 then
			out[i] = '\\"'
		elseif b == 92 then
			out[i] = "\\\\"
		elseif b >= 32 and b <= 126 then
			out[i] = string.char(b)
		elseif b == 10 then
			out[i] = "\\n"
		elseif b == 13 then
			out[i] = "\\r"
		else
			out[i] = string.format("\\%d", b)
		end
	end
	return '"' .. table.concat(out) .. '"'
end

local function __dump_val(v, seen, out)
	local t = type(v)

	if t == "number" then
		if v ~= v or v == math.huge or v == -math.huge then
			out[#out + 1] = "0"
		else
			out[#out + 1] = string.format("%.17g", v)
		end
	elseif t == "string" then
		out[#out + 1] = __dump_esc(v)
	elseif t == "boolean" then
		out[#out + 1] = tostring(v)
	elseif t == "table" then
		if seen[v] then
			out[#out + 1] = "nil"
			return
		end

		seen[v] = true
		out[#out + 1] = "{"

		local keys = {}

		for k in pairs(v) do
			keys[#keys + 1] = k
		end

		table.sort(keys, function(a, b)
			local ta, tb = type(a), type(b)

			if ta ~= tb then
				return ta < tb
			end

			if ta == "number" or ta == "string" then
				return a < b
			end

			return false
		end)

		for _, k in ipairs(keys) do
			out[#out + 1] = "["
			__dump_val(k, seen, out)
			out[#out + 1] = "]="
			__dump_val(v[k], seen, out)
			out[#out + 1] = ","
		end

		local mt = getmetatable(v)

		if mt ~= nil then
			local idx = rawget(mt, "__index")

			if type(idx) == "table" then
				out[#out + 1] = "__mt="
				__dump_val(idx, seen, out)
				out[#out + 1] = ","
			elseif idx ~= nil then
				out[#out + 1] = "__mtfunc=true,"
			end
		end

		out[#out + 1] = "}"
		seen[v] = nil
	else
		out[#out + 1] = "nil"
	end
end

local function __dump_count(v)
	local n = 0

	if type(v) == "table" then
		for _ in pairs(v) do
			n = n + 1
		end
	end

	return n
end

local function __dump_write(name, v)
	local safe = string.gsub(name, "[^%w%.%-]", "_")

	if __dumpSeen[safe] then
		__dumpSeen[safe] = __dumpSeen[safe] + 1
		safe = safe .. "." .. __dumpSeen[safe]
	else
		__dumpSeen[safe] = 1
	end

	local out = {}

	__dump_val(v, {}, out)

	local ok, err = pcall(function()
		local f = io.open(__dumpDir() .. safe .. ".lua", "wb")

		if f ~= nil then
			f:write("return ")
			f:write(table.concat(out))
			f:write("\n")
			f:close()
		end

		local m = io.open(__dumpDir() .. "manifest.txt", "a")

		if m ~= nil then
			m:write(string.format("%s\t%d\t%s\n", safe, __dump_count(v), os.date("%H:%M:%S")))
			m:close()
		end
	end)

	out = nil
	collectgarbage("collect")
	print("[H5DUMP] " .. safe .. " ok=" .. tostring(ok) .. (err and (" " .. tostring(err)) or ""))
end

local __dumpCurName = nil
local __dumpSeq = 0
local __dumpInstalled = false

local function __dump_install()
	if __dumpInstalled then
		return
	end

	__dumpInstalled = true

	local dpOrig = dataparser.parseData

	dataparser.parseData = function(buf, isTbl)
		local res = dpOrig(buf, isTbl)
		__dumpSeq = __dumpSeq + 1
		pcall(__dump_write, __dumpCurName or ("unknown_" .. __dumpSeq), res)
		return res
	end

	local dataOrig = Data.parseData

	Data.parseData = function(name, buf)
		__dumpCurName = tostring(name)
		local a, b, c = dataOrig(name, buf)
		__dumpCurName = nil
		return a, b, c
	end

	print("[H5DUMP] installed")
end

local function __dump_later()
	lc.Scheduler:scheduleScriptFunc(function(dt)
		pcall(function()
			local list = lc.App:loadRes("res/teach.lcres")

			for i = 1, #list do
				local name = list[i]

				if string.hasSuffix(name, ".bin") then
					local buf = lc.App:getBinData(name)

					if buf ~= nil then
						local res = dataparser.parseData(buf, true)

						if res == nil or (type(res) == "table" and __dump_count(res) == 0) then
							res = dataparser.parseData(buf, false)
						end

						pcall(__dump_write, "teach_" .. name, res)
						lc.App:unloadRes(name)
					end
				end
			end
		end)

		print("[H5DUMP] teach done")
	end, 8, false)
end
